    @asynccontextmanager
    async def _session_update(self, session_key: str):
        # Hold the existing lock through I/O so an older snapshot cannot win a race.
        async with self._lock:
            if not self._loaded:
                raise RuntimeError("HumanTakeover storage is not initialized")
